import ui_adapter.adapter.UIActionAdapter;
import ui_adapter.model.Action;
import ui_adapter.model.Selector;
import ui_adapter.model.Action.Type;
import ui_adapter.model.TestRunResult;
import ui_adapter.model.ActionResult;

import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        System.out.println("Starting UI Action Adapter Demo...");

        // 1. Define the actions to execute
        List<Action> actions = new ArrayList<>();

        // Action: Navigate to Google
        actions.add(new Action(
            Type.NAVIGATE, 
            null, 
            "https://www.google.com"
        ));

        // Action: Confirm search box is visible (using CSS selector for textarea)
        actions.add(new Action(
            Type.WAIT_FOR_VISIBLE,
            new Selector(Selector.Type.CSS, "textarea[name='q']"),
            null
        ));

        // Action: Type "Playwright Java"
        actions.add(new Action(
            Type.TYPE,
            new Selector(Selector.Type.CSS, "textarea[name='q']"),
            "Playwright Java"
        ));

        // Action: Click Google Search (using the 'btnK' button often found in the dropdown or main area)
        // Note: Google's home page structure changes often, so this is a best-effort example.
        // We often need to click outside or hit enter, but let's try a simple click logic or verify text instead for stability.
        actions.add(new Action(
             Type.ASSERT_VISIBLE,
             new Selector(Selector.Type.CSS, "img[alt='Google']"), 
             null
        ));

        // Action: Take a screenshot
        actions.add(new Action(
            Type.SCREENSHOT,
            null,
            null
        ));

        // 2. Instantiate the Adapter
        UIActionAdapter adapter = new UIActionAdapter();

        // 3. Run the actions
        TestRunResult result = adapter.runActions(actions);

        // 4. Print results
        System.out.println("--------------------------------------------------");
        System.out.println("Test Run Success: " + result.isSuccess());
        if (!result.isSuccess()) {
            System.err.println("Error: " + result.getErrorMessage());
        }

        System.out.println("Step Results:");
        for (ActionResult step : result.getStepResults()) {
            System.out.printf("[%s] %s%n", step.getStatus(), step.getMessage());
            if (step.getScreenshotPath() != null) {
                System.out.println("   Screenshot: " + step.getScreenshotPath());
            }
        }
        System.out.println("--------------------------------------------------");
    }
}

package ui_adapter.adapter;

import ui_adapter.driver.BrowserDriver;
import ui_adapter.driver.PlaywrightDriver;
import ui_adapter.executor.ActionExecutor;
import ui_adapter.model.Action;
import ui_adapter.model.ActionResult;
import ui_adapter.model.TestRunResult;
import ui_adapter.selector.SelectorResolver;

import java.util.ArrayList;
import java.util.List;

public class UIActionAdapter implements AutoCloseable {

    private final BrowserDriver driver;
    private final ActionExecutor executor;

    /**
     * Default constructor that creates a Playwright-backed driver.
     * The driver is started immediately so actions can be executed one-by-one.
     */
    public UIActionAdapter() {
        this(new PlaywrightDriver());
    }

    /**
     * Constructor for dependency injection / testing.
     */
    public UIActionAdapter(BrowserDriver driver) {
        this.driver = driver;
        this.driver.start();
        this.executor = new ActionExecutor(this.driver, new SelectorResolver());
    }

    /**
     * Execute exactly one action and return its result.
     * No retries, no decision logic.
     */
    public ActionResult execute(Action action) {
        return executor.execute(action);
    }

    /**
     * Executes a list of UI actions sequentially.
     * Stops execution on the first failure.
     */
    public TestRunResult runActions(List<Action> actions) {
        if (actions == null || actions.isEmpty()) {
            return new TestRunResult(true, new ArrayList<>(), "No actions to execute");
        }

        List<ActionResult> stepResults = new ArrayList<>();
        boolean overallSuccess = true;
        String errorMessage = null;

        for (Action action : actions) {
            ActionResult result = execute(action);
            stepResults.add(result);

            if (result.getStatus() == ActionResult.Status.FAIL) {
                overallSuccess = false;
                errorMessage = "Execution stopped due to failure at step " + stepResults.size() + ": " + result.getMessage();
                break;
            }
        }

        return new TestRunResult(overallSuccess, stepResults, errorMessage);
    }

    @Override
    public void close() {
        if (driver != null) {
            driver.close();
        }
    }
}

package ui_adapter.adapter;

import ui_adapter.driver.BrowserDriver;
import ui_adapter.driver.PlaywrightDriver;
import ui_adapter.executor.ActionExecutor;
import ui_adapter.model.Action;
import ui_adapter.model.ActionResult;
import ui_adapter.model.TestRunResult;
import ui_adapter.selector.SelectorResolver;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;

public class UIActionAdapter implements AutoCloseable {

    private final BrowserDriver driver;
    private final ActionExecutor executor;

    private long stepCounter = 0;
    private boolean loggingEnabled = true;

    /**
     * Default constructor that creates a Playwright-backed driver.
     * The driver is started immediately so actions can be executed one-by-one.
     */
    public UIActionAdapter() {
        this(new PlaywrightDriver());
    }

    /**
     * Constructor for dependency injection / testing.
     */
    public UIActionAdapter(BrowserDriver driver) {
        this.driver = driver;
        this.driver.start();
        this.executor = new ActionExecutor(this.driver, new SelectorResolver());
    }

    /** Enable/disable adapter-level logging (executor remains unchanged). */
    public void setLoggingEnabled(boolean enabled) {
        this.loggingEnabled = enabled;
    }

    /**
     * Execute exactly one action and return its result.
     * No retries, no decision logic.
     */
    public ActionResult execute(Action action) {
        stepCounter++;

        Instant start = Instant.now();
        if (loggingEnabled) {
            System.out.println(formatHeader(stepCounter, action));
        }

        ActionResult result = executor.execute(action);

        if (loggingEnabled) {
            long ms = Duration.between(start, Instant.now()).toMillis();
            System.out.println(formatResult(stepCounter, result, ms));
        }

        return result;
    }

    /**
     * Executes a list of UI actions sequentially.
     * Stops execution on the first failure.
     */
    public TestRunResult runActions(List<Action> actions) {
        if (actions == null || actions.isEmpty()) {
            return new TestRunResult(true, new ArrayList<>(), "No actions to execute");
        }

        List<ActionResult> stepResults = new ArrayList<>();
        boolean overallSuccess = true;
        String errorMessage = null;

        for (Action action : actions) {
            ActionResult result = execute(action);
            stepResults.add(result);

            if (result.getStatus() == ActionResult.Status.FAIL) {
                overallSuccess = false;
                errorMessage = "Execution stopped due to failure at step " + stepResults.size() + ": " + result.getMessage();
                break;
            }
        }

        return new TestRunResult(overallSuccess, stepResults, errorMessage);
    }

    @Override
    public void close() {
        if (loggingEnabled) {
            System.out.println("[ADAPTER] Closing browser driver");
        }
        if (driver != null) {
            driver.close();
        }
    }

    private String formatHeader(long step, Action action) {
        String selector = (action.getSelector() == null) ? "<none>" : action.getSelector().toString();
        String value = (action.getValue() == null) ? "<none>" : action.getValue();
        return String.format("%n[STEP %03d] EXECUTE  type=%s  selector=%s  value=%s", step, action.getType(), selector, value);
    }

    private String formatResult(long step, ActionResult result, long durationMs) {
        String errorType = (result.getErrorType() == null) ? "<none>" : result.getErrorType().name();
        String screenshot = (result.getScreenshotPath() == null) ? "<none>" : result.getScreenshotPath();
        return String.format("[STEP %03d] RESULT   status=%s  errorType=%s  durationMs=%d  screenshot=%s%n           message=%s", step, result.getStatus(), errorType, durationMs, screenshot, result.getMessage());
    }
}

package ui_adapter.agent;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import ui_adapter.model.Action;
import ui_adapter.model.ActionResult;
import ui_adapter.model.Selector;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * An agent that uses the Groq API (OpenAI compatible) to decide the next action.
 * <p>
 * It sends the conversation history (system prompt + previous results) to the LLM
 * and expects a JSON response corresponding to a deterministic UI Action.
 */
public class LlmAgent implements TestAgent {

    private static final String API_URL = "https://api.groq.com/openai/v1/chat/completions";
    // NOTE: In production, do not hardcode keys. Use environment variables.
    private static final String API_KEY = getApiKey();
    private static final String MODEL = "openai/gpt-oss-safeguard-20b"; // Change this string to switch models (e.g., "mixtral-8x7b-32768")

    private final String goal;
    private final List<JsonObject> messages;
    private final Gson gson;
    private final Gson prettyGson = new GsonBuilder().setPrettyPrinting().create();
    private final HttpClient client;
    private final ExecutorService executorService; // Manage threads manually to avoid warnings
    private boolean isComplete = false;
    private int consecutiveFailures = 0;
    private static final int MAX_CONSECUTIVE_FAILURES = 3;
    private static final boolean LLM_WIRE_LOG_ENABLED = true;
    private static final int LLM_MAX_MESSAGES_TO_LOG = 6;

    private static String getApiKey() {
        String key = System.getenv("GROQ_API_KEY");
        if (key == null || key.isEmpty()) {
            key = System.getProperty("GROQ_API_KEY");
        }
        return key;
    }

    public LlmAgent(String goal) {
        this.goal = goal;
        this.gson = new Gson();

        // Use a daemon thread executor so the JVM exits promptly
        this.executorService = Executors.newCachedThreadPool(r -> {
            Thread t = new Thread(r);
            t.setDaemon(true);
            return t;
        });

        this.client = HttpClient.newBuilder()
                .executor(executorService)
                .build();

        this.messages = new ArrayList<>();

        // 1. Initialize System Prompt
        JsonObject systemMessage = new JsonObject();
        systemMessage.addProperty("role", "system");
        systemMessage.addProperty("content", getSystemPrompt());
        this.messages.add(systemMessage);

        // 2. Add User Goal
        JsonObject goalMessage = new JsonObject();
        goalMessage.addProperty("role", "user");
        goalMessage.addProperty("content", "GOAL: " + goal);
        this.messages.add(goalMessage);
    }

    @Override
    public Action nextAction(ActionResult previousResult) {
        if (isComplete) {
            return null; // Stop
        }

        // 3. Append result of the previous action (if any)
        if (previousResult != null) {
            JsonObject resultMessage = new JsonObject();
            resultMessage.addProperty("role", "user");
            resultMessage.addProperty("content", "ACTION_RESULT: " + previousResult.toString());
            messages.add(resultMessage);

            if (previousResult.getStatus() == ActionResult.Status.FAIL) {
                consecutiveFailures++;
                System.err.println("Action failed (" + consecutiveFailures + "/" + MAX_CONSECUTIVE_FAILURES + "): " + previousResult.getMessage());

                if (consecutiveFailures >= MAX_CONSECUTIVE_FAILURES) {
                    System.err.println("Too many consecutive failures. Stopping.");
                    isComplete = true;
                    return null;
                }

                // Do NOT stop immediately. Let the LLM try to "heal" or try a different approach.
            } else {
                consecutiveFailures = 0; // Reset on success
            }
        }

        // 4. Call LLM to get the NEXT action
        try {
            String jsonResponse;
            try {
                jsonResponse = callGroqApi();
            } catch (RuntimeException apiEx) {
                // If the API rejects a tool-call style generation, attempt to recover using failed_generation.
                String recovered = tryRecoverFailedGenerationJson(apiEx.getMessage());
                if (recovered != null) {
                    jsonResponse = recovered;
                } else {
                    throw apiEx;
                }
            }

            Action action = parseLlmResponse(jsonResponse);

            // Add the assistant's decision to history
            JsonObject assistantMessage = new JsonObject();
            assistantMessage.addProperty("role", "assistant");
            assistantMessage.addProperty("content", gson.toJson(action));
            messages.add(assistantMessage);

            if (LLM_WIRE_LOG_ENABLED) {
                System.out.println("[LLM] NEXT ACTION => " + summarizeAction(action));
            }

            return action;

        } catch (Exception e) {
            // Don't print null; include class for easier debugging
            System.err.println("[LLM] ERROR: " + (e.getMessage() == null ? e.getClass().getSimpleName() : e.getMessage()));
            isComplete = true;
            return null;
        }
    }

    @Override
    public boolean isTestComplete() {
        return isComplete;
    }

    @Override
    public void onTestEnd(List<ActionResult> results) {
        System.out.println("LLM Agent finished. Total steps: " + results.size());
        // Cleanup resources
        if (executorService != null) {
            executorService.shutdownNow();
        }
    }

    // --- Private Helpers ---

    private String callGroqApi() throws Exception {
        if (API_KEY == null || API_KEY.isEmpty()) {
            throw new IllegalStateException("GROQ_API_KEY environment variable is missing!");
        }

        JsonObject requestBody = new JsonObject();
        requestBody.addProperty("model", MODEL);
        requestBody.addProperty("temperature", 0.0);

        // Create request messages as-is, but in logs only show a tail (last N)
        JsonArray messagesArray = new JsonArray();
        for (JsonObject m : messages) {
            messagesArray.add(m);
        }
        requestBody.add("messages", messagesArray);

        JsonObject responseFormat = new JsonObject();
        responseFormat.addProperty("type", "json_object");
        requestBody.add("response_format", responseFormat);

        String jsonBody = gson.toJson(requestBody);

        if (LLM_WIRE_LOG_ENABLED) {
            System.out.println("\n==================================================");
            System.out.println("[LLM] REQUEST");
            System.out.println("  url   : " + API_URL);
            System.out.println("  model : " + MODEL);
            System.out.println("  temp  : 0.0");
            System.out.println("\n[LLM] MESSAGES (last " + LLM_MAX_MESSAGES_TO_LOG + "):");
            logMessageTail();
            System.out.println("\n[LLM] FULL REQUEST JSON:");
            System.out.println(prettyGson.toJson(JsonParser.parseString(jsonBody)));
            System.out.println("==================================================");
        }

        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(API_URL))
                .header("Content-Type", "application/json")
                .header("Authorization", "Bearer " + API_KEY)
                .POST(HttpRequest.BodyPublishers.ofString(jsonBody))
                .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

        if (LLM_WIRE_LOG_ENABLED) {
            System.out.println("\n==================================================");
            System.out.println("[LLM] RESPONSE");
            System.out.println("  status : " + response.statusCode());
            System.out.println("\n[LLM] RAW RESPONSE JSON:");
            try {
                System.out.println(prettyGson.toJson(JsonParser.parseString(response.body())));
            } catch (Exception ignore) {
                System.out.println(response.body());
            }
            System.out.println("==================================================");
        }

        if (response.statusCode() != 200) {
            throw new RuntimeException("API Error: " + response.statusCode() + " " + response.body());
        }
        return response.body();
    }

    private Action parseLlmResponse(String jsonResponse) {
        // Extract content from Groq response structure
        JsonObject root = JsonParser.parseString(jsonResponse).getAsJsonObject();
        JsonArray choices = root.getAsJsonArray("choices");
        String content = choices.get(0).getAsJsonObject()
                .getAsJsonObject("message")
                .get("content").getAsString();

        // The model should return a JSON object, but some models return a JSON array of actions.
        var parsed = JsonParser.parseString(content);
        JsonObject decision;
        if (parsed.isJsonArray()) {
            JsonArray arr = parsed.getAsJsonArray();
            if (arr.isEmpty() || !arr.get(0).isJsonObject()) {
                throw new IllegalArgumentException("Invalid LLM response: expected non-empty JSON array of objects");
            }
            decision = arr.get(0).getAsJsonObject();
        } else {
            decision = parsed.getAsJsonObject();
        }

        // Some models sometimes wrap the actual payload as a tool-call-like object:
        // { "name": "assistant", "arguments": { ...actual decision... } }
        if (decision.has("arguments") && decision.get("arguments").isJsonObject()) {
            decision = decision.getAsJsonObject("arguments");
        }

        // Print the Agent's reasoning (Chain of Thought)
        if (decision.has("thought")) {
            System.out.println("\n[AGENT THOUGHT]: " + decision.get("thought").getAsString());
        }

        // Check if agent wants to stop
        if (decision.has("isComplete") && decision.get("isComplete").getAsBoolean()) {
            isComplete = true;
            return null;
        }

        // Parse Action Type
        String typeStr = decision.get("type").getAsString();
        Action.Type actionType = Action.Type.valueOf(typeStr.toUpperCase());

        // Parse Selector (nullable)
        Selector selector = null;
        if (decision.has("selector") && !decision.get("selector").isJsonNull()) {
            JsonObject selObj = decision.getAsJsonObject("selector");
            String selTypeStr = selObj.get("type").getAsString();
            String selVal = selObj.get("value").getAsString();

            // If the model emits selector.type=URL, treat it as NAVIGATE url in the action.value.
            if ("URL".equalsIgnoreCase(selTypeStr) && (decision.get("value").isJsonNull() || decision.get("value").getAsString().isEmpty())) {
                // Keep selector null for navigate, value will be read below.
            } else {
                String role = null;
                String nearText = null;
                String description = null;

                if (selObj.has("meta") && !selObj.get("meta").isJsonNull()) {
                    JsonObject meta = selObj.getAsJsonObject("meta");
                    if (meta.has("role") && !meta.get("role").isJsonNull()) {
                        role = meta.get("role").getAsString();
                    }
                    if (meta.has("nearText") && !meta.get("nearText").isJsonNull()) {
                        nearText = meta.get("nearText").getAsString();
                    }
                    if (meta.has("description") && !meta.get("description").isJsonNull()) {
                        description = meta.get("description").getAsString();
                    }
                }

                selector = new Selector(Selector.Type.valueOf(selTypeStr.toUpperCase()), selVal, role, nearText, description);
            }
        }

        // Parse Value (nullable)
        String value = null;
        if (decision.has("value") && !decision.get("value").isJsonNull()) {
            value = decision.get("value").getAsString();
        }

        // If selector.type was URL, value should come from selector.value
        if (value == null && decision.has("selector") && !decision.get("selector").isJsonNull()) {
            JsonObject selObj = decision.getAsJsonObject("selector");
            if (selObj.has("type") && "URL".equalsIgnoreCase(selObj.get("type").getAsString()) && selObj.has("value")) {
                value = selObj.get("value").getAsString();
            }
        }

        return new Action(actionType, selector, value);
    }

    private void logMessageTail() {
        int start = Math.max(0, messages.size() - LLM_MAX_MESSAGES_TO_LOG);
        for (int i = start; i < messages.size(); i++) {
            JsonObject m = messages.get(i);
            String role = m.has("role") ? m.get("role").getAsString() : "?";
            String content = m.has("content") ? m.get("content").getAsString() : "";
            System.out.println(String.format("  - [%s] %s", role, oneLine(content, 240)));
        }
    }

    private static String oneLine(String s, int maxLen) {
        if (s == null) {
            return "";
        }
        String cleaned = s.replace("\r", " ").replace("\n", " ").replaceAll("\\s+", " ").trim();
        if (cleaned.length() <= maxLen) {
            return cleaned;
        }
        return cleaned.substring(0, maxLen) + "...";
    }

    private static String summarizeAction(Action action) {
        if (action == null) {
            return "<null>";
        }
        String selector = (action.getSelector() == null) ? "<none>" : action.getSelector().toString();
        String value = (action.getValue() == null) ? "<none>" : action.getValue();
        return "type=" + action.getType() + ", selector=" + selector + ", value=" + value;
    }

    private static String tryRecoverFailedGenerationJson(String errorMessage) {
        try {
            if (errorMessage == null) {
                return null;
            }
            int firstBrace = errorMessage.indexOf("{");
            if (firstBrace < 0) {
                return null;
            }
            String maybeJson = errorMessage.substring(firstBrace);
            JsonObject root = JsonParser.parseString(maybeJson).getAsJsonObject();
            if (!root.has("error")) {
                return null;
            }
            JsonObject err = root.getAsJsonObject("error");
            if (!err.has("failed_generation")) {
                return null;
            }
            String failed = err.get("failed_generation").getAsString();

            // If failed_generation is a tool-call-like wrapper, unwrap it.
            // Example: {"name":"type","arguments":{...}}
            try {
                var failedParsed = JsonParser.parseString(failed);
                if (failedParsed.isJsonObject()) {
                    JsonObject fo = failedParsed.getAsJsonObject();
                    if (fo.has("arguments") && fo.get("arguments").isJsonObject()) {
                        failed = fo.getAsJsonObject("arguments").toString();
                    }
                }
            } catch (Exception ignore) {
                // keep original failed string
            }

            // Wrap into a minimal "choices/message/content" response so existing parsing works.
            JsonObject fake = new JsonObject();
            JsonArray choices = new JsonArray();
            JsonObject choice0 = new JsonObject();
            JsonObject msg = new JsonObject();
            msg.addProperty("content", failed);
            choice0.add("message", msg);
            choices.add(choice0);
            fake.add("choices", choices);
            return fake.toString();
        } catch (Exception ignore) {
            return null;
        }
    }

    private String getSystemPrompt() {
        return "You are a UI Test Automation Agent. Your goal is to navigate a website and perform actions to achieve a user goal.\n" +
                "You must output STRICT JSON ONLY. No markdown, no explanations outside the JSON.\n" +
                "IMPORTANT: Output exactly ONE action JSON object (not an array).\n" +
                "IMPORTANT: Do NOT output tool/function-call wrappers like {\\\"name\\\":..., \\\"arguments\\\":...}.\n" +
                "IMPORTANT: The 'type' field MUST be one of the allowed action types listed below.\n" +
                "IMPORTANT: The selector.type field MUST be one of: CSS | XPATH | TEXT | ROLE | LABEL | PLACEHOLDER | TEST_ID. Do NOT use URL.\n" +
                "For NAVIGATE actions, put the URL in the top-level 'value' field and set selector to null.\n" +
                "\n" +
                "Output format:\n" +
                "{\n" +
                "  \"thought\": \"Brief reasoning about what to do next based on the last result\",\n" +
                "  \"type\": \"NAVIGATE | CLICK | TYPE | WAIT_FOR_VISIBLE | ASSERT_VISIBLE | ASSERT_TEXT | SCREENSHOT | SCROLL | SWITCH_TAB\",\n" +
                "  \"selector\": {\n" +
                "    \"type\": \"CSS | XPATH | TEXT | ROLE | LABEL | PLACEHOLDER | TEST_ID\",\n" +
                "    \"value\": \"selector value\",\n" +
                "    \"meta\": {\n" +
                "      \"role\": \"optional ARIA role like button, link, textbox, checkbox, etc.\",\n" +
                "      \"nearText\": \"optional nearby or surrounding text to help disambiguate\",\n" +
                "      \"description\": \"short natural-language description of the element if helpful\"\n" +
                "    }\n" +
                "  } (or null if not needed),\n" +
                "  \"value\": \"text to type or url or scroll amount or tab index\" (or null),\n" +
                "  \"isComplete\": boolean (true if goal achieved)\n" +
                "}\n" +
                "\n" +
                "Guidance on Selectors:\n" +
                "- Prefer semantic selectors (ROLE/LABEL/PLACEHOLDER/TEST_ID/TEXT). Avoid complex CSS/XPATH unless necessary.\n" +
                "- If multiple elements match a TEXT selector, prefer the element that is a BUTTON or LINK.\n" +
                "\n" +
                "Step-by-step logic:\n" +
                "1. Always NAVIGATE first if history is empty.\n" +
                "2. If a page load is expected, use WAIT_FOR_VISIBLE before interacting.\n" +
                "3. If a popup or new tab opens (e.g., SSO), use SWITCH_TAB.\n" +
                "\n";
    }
}

package ui_adapter.agent;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import ui_adapter.model.Action;
import ui_adapter.model.ActionResult;
import ui_adapter.model.Selector;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * An agent that uses the Groq API (OpenAI compatible) to decide the next action.
 * <p>
 * It sends the conversation history (system prompt + previous results) to the LLM
 * and expects a JSON response corresponding to a deterministic UI Action.
 */
public class LlmAgent implements TestAgent {

    private static final String API_URL = "https://api.groq.com/openai/v1/chat/completions";
    // NOTE: In production, do not hardcode keys. Use environment variables.
    private static final String API_KEY = getApiKey();
    private static final String MODEL = "openai/gpt-oss-safeguard-20b"; // Change this string to switch models (e.g., "mixtral-8x7b-32768")

    private final String goal;
    private final List<JsonObject> messages;
    private final Gson gson;
    private final Gson prettyGson = new GsonBuilder().setPrettyPrinting().create();
    private final HttpClient client;
    private final ExecutorService executorService; // Manage threads manually to avoid warnings
    private boolean isComplete = false;
    private int consecutiveFailures = 0;
    private static final int MAX_CONSECUTIVE_FAILURES = 3;
    private static final boolean LLM_WIRE_LOG_ENABLED = true;
    private static final int LLM_MAX_MESSAGES_TO_LOG = 6;

    private static String getApiKey() {
        String key = System.getenv("GROQ_API_KEY");
        if (key == null || key.isEmpty()) {
            key = System.getProperty("GROQ_API_KEY");
        }
        return key;
    }

    public LlmAgent(String goal) {
        this.goal = goal;
        this.gson = new Gson();

        // Use a daemon thread executor so the JVM exits promptly
        this.executorService = Executors.newCachedThreadPool(r -> {
            Thread t = new Thread(r);
            t.setDaemon(true);
            return t;
        });

        this.client = HttpClient.newBuilder()
                .executor(executorService)
                .build();

        this.messages = new ArrayList<>();

        // 1. Initialize System Prompt
        JsonObject systemMessage = new JsonObject();
        systemMessage.addProperty("role", "system");
        systemMessage.addProperty("content", getSystemPrompt());
        this.messages.add(systemMessage);

        // 2. Add User Goal
        JsonObject goalMessage = new JsonObject();
        goalMessage.addProperty("role", "user");
        goalMessage.addProperty("content", "GOAL: " + goal);
        this.messages.add(goalMessage);
    }

    @Override
    public Action nextAction(ActionResult previousResult) {
        if (isComplete) {
            return null; // Stop
        }

        // 3. Append result of the previous action (if any)
        if (previousResult != null) {
            JsonObject resultMessage = new JsonObject();
            resultMessage.addProperty("role", "user");
            resultMessage.addProperty("content", "ACTION_RESULT: " + previousResult.toString());
            messages.add(resultMessage);

            if (previousResult.getStatus() == ActionResult.Status.FAIL) {
                consecutiveFailures++;
                System.err.println("Action failed (" + consecutiveFailures + "/" + MAX_CONSECUTIVE_FAILURES + "): " + previousResult.getMessage());

                if (consecutiveFailures >= MAX_CONSECUTIVE_FAILURES) {
                    System.err.println("Too many consecutive failures. Stopping.");
                    isComplete = true;
                    return null;
                }

                // Do NOT stop immediately. Let the LLM try to "heal" or try a different approach.
            } else {
                consecutiveFailures = 0; // Reset on success
            }
        }

        // 4. Call LLM to get the NEXT action
        try {
            String jsonResponse;
            try {
                jsonResponse = callGroqApi();
            } catch (RuntimeException apiEx) {
                // If the API rejects a tool-call style generation, attempt to recover using failed_generation.
                String recovered = tryRecoverFailedGenerationJson(apiEx.getMessage());
                if (recovered != null) {
                    jsonResponse = recovered;
                } else {
                    throw apiEx;
                }
            }

            Action action = parseLlmResponse(jsonResponse);

            // Add the assistant's decision to history
            JsonObject assistantMessage = new JsonObject();
            assistantMessage.addProperty("role", "assistant");
            assistantMessage.addProperty("content", gson.toJson(action));
            messages.add(assistantMessage);

            if (LLM_WIRE_LOG_ENABLED) {
                System.out.println("[LLM] NEXT ACTION => " + summarizeAction(action));
            }

            return action;

        } catch (Exception e) {
            // Don't print null; include class for easier debugging
            System.err.println("[LLM] ERROR: " + (e.getMessage() == null ? e.getClass().getSimpleName() : e.getMessage()));
            isComplete = true;
            return null;
        }
    }

    @Override
    public boolean isTestComplete() {
        return isComplete;
    }

    @Override
    public void onTestEnd(List<ActionResult> results) {
        System.out.println("LLM Agent finished. Total steps: " + results.size());
        // Cleanup resources
        if (executorService != null) {
            executorService.shutdownNow();
        }
    }

    // --- Private Helpers ---

    private String callGroqApi() throws Exception {
        if (API_KEY == null || API_KEY.isEmpty()) {
            throw new IllegalStateException("GROQ_API_KEY environment variable is missing!");
        }

        JsonObject requestBody = new JsonObject();
        requestBody.addProperty("model", MODEL);
        requestBody.addProperty("temperature", 0.0);

        // Create request messages as-is, but in logs only show a tail (last N)
        JsonArray messagesArray = new JsonArray();
        for (JsonObject m : messages) {
            messagesArray.add(m);
        }
        requestBody.add("messages", messagesArray);

        JsonObject responseFormat = new JsonObject();
        responseFormat.addProperty("type", "json_object");
        requestBody.add("response_format", responseFormat);

        String jsonBody = gson.toJson(requestBody);

        if (LLM_WIRE_LOG_ENABLED) {
            System.out.println("\n==================================================");
            System.out.println("[LLM] REQUEST");
            System.out.println("  url   : " + API_URL);
            System.out.println("  model : " + MODEL);
            System.out.println("  temp  : 0.0");
            System.out.println("\n[LLM] MESSAGES (last " + LLM_MAX_MESSAGES_TO_LOG + "):");
            logMessageTail();
            System.out.println("\n[LLM] FULL REQUEST JSON:");
            System.out.println(prettyGson.toJson(JsonParser.parseString(jsonBody)));
            System.out.println("==================================================");
        }

        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(API_URL))
                .header("Content-Type", "application/json")
                .header("Authorization", "Bearer " + API_KEY)
                .POST(HttpRequest.BodyPublishers.ofString(jsonBody))
                .build();

        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());

        if (LLM_WIRE_LOG_ENABLED) {
            System.out.println("\n==================================================");
            System.out.println("[LLM] RESPONSE");
            System.out.println("  status : " + response.statusCode());
            System.out.println("\n[LLM] RAW RESPONSE JSON:");
            try {
                System.out.println(prettyGson.toJson(JsonParser.parseString(response.body())));
            } catch (Exception ignore) {
                System.out.println(response.body());
            }
            System.out.println("==================================================");
        }

        if (response.statusCode() != 200) {
            throw new RuntimeException("API Error: " + response.statusCode() + " " + response.body());
        }
        return response.body();
    }

    private Action parseLlmResponse(String jsonResponse) {
        // Extract content from Groq response structure
        JsonObject root = JsonParser.parseString(jsonResponse).getAsJsonObject();
        JsonArray choices = root.getAsJsonArray("choices");
        String content = choices.get(0).getAsJsonObject()
                .getAsJsonObject("message")
                .get("content").getAsString();

        // The model should return a JSON object, but some models return a JSON array of actions.
        var parsed = JsonParser.parseString(content);
        JsonObject decision;
        if (parsed.isJsonArray()) {
            JsonArray arr = parsed.getAsJsonArray();
            if (arr.isEmpty() || !arr.get(0).isJsonObject()) {
                throw new IllegalArgumentException("Invalid LLM response: expected non-empty JSON array of objects");
            }
            decision = arr.get(0).getAsJsonObject();
        } else {
            decision = parsed.getAsJsonObject();
        }

        // Some models sometimes wrap the actual payload as a tool-call-like object:
        // { "name": "assistant", "arguments": { ...actual decision... } }
        if (decision.has("arguments") && decision.get("arguments").isJsonObject()) {
            decision = decision.getAsJsonObject("arguments");
        }

        // Print the Agent's reasoning (Chain of Thought)
        if (decision.has("thought")) {
            System.out.println("\n[AGENT THOUGHT]: " + decision.get("thought").getAsString());
        }

        // Check if agent wants to stop
        if (decision.has("isComplete") && decision.get("isComplete").getAsBoolean()) {
            isComplete = true;
            return null;
        }

        // Parse Action Type
        String typeStr = decision.get("type").getAsString();
        Action.Type actionType = Action.Type.valueOf(typeStr.toUpperCase());

        // Parse Selector (nullable)
        Selector selector = null;
        if (decision.has("selector") && !decision.get("selector").isJsonNull()) {
            JsonObject selObj = decision.getAsJsonObject("selector");
            String selTypeStr = selObj.get("type").getAsString();
            String selVal = selObj.get("value").getAsString();

            // If the model emits selector.type=URL, treat it as NAVIGATE url in the action.value.
            if ("URL".equalsIgnoreCase(selTypeStr) && (decision.get("value").isJsonNull() || decision.get("value").getAsString().isEmpty())) {
                // Keep selector null for navigate, value will be read below.
            } else {
                String role = null;
                String nearText = null;
                String description = null;

                if (selObj.has("meta") && !selObj.get("meta").isJsonNull()) {
                    JsonObject meta = selObj.getAsJsonObject("meta");
                    if (meta.has("role") && !meta.get("role").isJsonNull()) {
                        role = meta.get("role").getAsString();
                    }
                    if (meta.has("nearText") && !meta.get("nearText").isJsonNull()) {
                        nearText = meta.get("nearText").getAsString();
                    }
                    if (meta.has("description") && !meta.get("description").isJsonNull()) {
                        description = meta.get("description").getAsString();
                    }
                }

                selector = new Selector(Selector.Type.valueOf(selTypeStr.toUpperCase()), selVal, role, nearText, description);
            }
        }

        // Parse Value (nullable)
        String value = null;
        if (decision.has("value") && !decision.get("value").isJsonNull()) {
            value = decision.get("value").getAsString();
        }

        // If selector.type was URL, value should come from selector.value
        if (value == null && decision.has("selector") && !decision.get("selector").isJsonNull()) {
            JsonObject selObj = decision.getAsJsonObject("selector");
            if (selObj.has("type") && "URL".equalsIgnoreCase(selObj.get("type").getAsString()) && selObj.has("value")) {
                value = selObj.get("value").getAsString();
            }
        }

        return new Action(actionType, selector, value);
    }

    private void logMessageTail() {
        int start = Math.max(0, messages.size() - LLM_MAX_MESSAGES_TO_LOG);
        for (int i = start; i < messages.size(); i++) {
            JsonObject m = messages.get(i);
            String role = m.has("role") ? m.get("role").getAsString() : "?";
            String content = m.has("content") ? m.get("content").getAsString() : "";
            System.out.println(String.format("  - [%s] %s", role, oneLine(content, 240)));
        }
    }

    private static String oneLine(String s, int maxLen) {
        if (s == null) {
            return "";
        }
        String cleaned = s.replace("\r", " ").replace("\n", " ").replaceAll("\\s+", " ").trim();
        if (cleaned.length() <= maxLen) {
            return cleaned;
        }
        return cleaned.substring(0, maxLen) + "...";
    }

    private static String summarizeAction(Action action) {
        if (action == null) {
            return "<null>";
        }
        String selector = (action.getSelector() == null) ? "<none>" : action.getSelector().toString();
        String value = (action.getValue() == null) ? "<none>" : action.getValue();
        return "type=" + action.getType() + ", selector=" + selector + ", value=" + value;
    }

    private static String tryRecoverFailedGenerationJson(String errorMessage) {
        try {
            if (errorMessage == null) {
                return null;
            }
            int firstBrace = errorMessage.indexOf("{");
            if (firstBrace < 0) {
                return null;
            }
            String maybeJson = errorMessage.substring(firstBrace);
            JsonObject root = JsonParser.parseString(maybeJson).getAsJsonObject();
            if (!root.has("error")) {
                return null;
            }
            JsonObject err = root.getAsJsonObject("error");
            if (!err.has("failed_generation")) {
                return null;
            }
            String failed = err.get("failed_generation").getAsString();

            // If failed_generation is a tool-call-like wrapper, unwrap it.
            // Example: {"name":"type","arguments":{...}}
            try {
                var failedParsed = JsonParser.parseString(failed);
                if (failedParsed.isJsonObject()) {
                    JsonObject fo = failedParsed.getAsJsonObject();
                    if (fo.has("arguments") && fo.get("arguments").isJsonObject()) {
                        failed = fo.getAsJsonObject("arguments").toString();
                    }
                }
            } catch (Exception ignore) {
                // keep original failed string
            }

            // Wrap into a minimal "choices/message/content" response so existing parsing works.
            JsonObject fake = new JsonObject();
            JsonArray choices = new JsonArray();
            JsonObject choice0 = new JsonObject();
            JsonObject msg = new JsonObject();
            msg.addProperty("content", failed);
            choice0.add("message", msg);
            choices.add(choice0);
            fake.add("choices", choices);
            return fake.toString();
        } catch (Exception ignore) {
            return null;
        }
    }

    private String getSystemPrompt() {
        return "You are a UI Test Automation Agent. Your goal is to navigate a website and perform actions to achieve a user goal.\n" +
                "You must output STRICT JSON ONLY. No markdown, no explanations outside the JSON.\n" +
                "IMPORTANT: Output exactly ONE action JSON object (not an array).\n" +
                "IMPORTANT: Do NOT output tool/function-call wrappers like {\\\"name\\\":..., \\\"arguments\\\":...}.\n" +
                "IMPORTANT: The 'type' field MUST be one of the allowed action types listed below.\n" +
                "IMPORTANT: The selector.type field MUST be one of: CSS | XPATH | TEXT | ROLE | LABEL | PLACEHOLDER | TEST_ID. Do NOT use URL.\n" +
                "For NAVIGATE actions, put the URL in the top-level 'value' field and set selector to null.\n" +
                "\n" +
                "Output format:\n" +
                "{\n" +
                "  \"thought\": \"Brief reasoning about what to do next based on the last result\",\n" +
                "  \"type\": \"NAVIGATE | CLICK | TYPE | WAIT_FOR_VISIBLE | ASSERT_VISIBLE | ASSERT_TEXT | SCREENSHOT | SCROLL | SWITCH_TAB\",\n" +
                "  \"selector\": {\n" +
                "    \"type\": \"CSS | XPATH | TEXT | ROLE | LABEL | PLACEHOLDER | TEST_ID\",\n" +
                "    \"value\": \"selector value\",\n" +
                "    \"meta\": {\n" +
                "      \"role\": \"optional ARIA role like button, link, textbox, checkbox, etc.\",\n" +
                "      \"nearText\": \"optional nearby or surrounding text to help disambiguate\",\n" +
                "      \"description\": \"short natural-language description of the element if helpful\"\n" +
                "    }\n" +
                "  } (or null if not needed),\n" +
                "  \"value\": \"text to type or url or scroll amount or tab index\" (or null),\n" +
                "  \"isComplete\": boolean (true if goal achieved)\n" +
                "}\n" +
                "\n" +
                "Guidance on Selectors:\n" +
                "- Prefer semantic selectors (ROLE/LABEL/PLACEHOLDER/TEST_ID/TEXT). Avoid complex CSS/XPATH unless necessary.\n" +
                "- If multiple elements match a TEXT selector, prefer the element that is a BUTTON or LINK.\n" +
                "\n" +
                "Step-by-step logic:\n" +
                "1. Always NAVIGATE first if history is empty.\n" +
                "2. If a page load is expected, use WAIT_FOR_VISIBLE before interacting.\n" +
                "3. If a popup or new tab opens (e.g., SSO), use SWITCH_TAB.\n" +
                "\n";
    }
}

package ui_adapter.agent;

import ui_adapter.model.Action;
import ui_adapter.model.ActionResult;
import ui_adapter.model.Selector;

import java.util.ArrayList;
import java.util.List;

/**
 * Reference deterministic agent implementation (no AI).
 *
 * Produces actions sequentially for a fixed scenario and may stop early on failure.
 */
public class SimpleRuleAgent implements TestAgent {

    private final String scenarioText;
    private final List<Action> plan;
    private int index = 0;
    private boolean complete = false;

    public SimpleRuleAgent(String scenarioText) {
        this.scenarioText = scenarioText;
        this.plan = buildPlan();
    }

    @Override
    public Action nextAction(ActionResult previousResult) {
        if (complete) {
            return null;
        }

        // Agent reacts to failure by stopping (no retries / no healing).
        if (previousResult != null && previousResult.getStatus() == ActionResult.Status.FAIL) {
            complete = true;
            return null;
        }

        if (index >= plan.size()) {
            complete = true;
            return null;
        }

        return plan.get(index++);
    }

    @Override
    public boolean isTestComplete() {
        return complete;
    }

    @Override
    public void onTestEnd(List<ActionResult> results) {
        // No external calls; deterministic summary hook.
        int pass = 0;
        int fail = 0;
        for (ActionResult r : results) {
            if (r.getStatus() == ActionResult.Status.PASS) {
                pass++;
            } else {
                fail++;
            }
        }
        System.out.println("Scenario: " + scenarioText);
        System.out.println("Results: PASS=" + pass + ", FAIL=" + fail);
    }

    private List<Action> buildPlan() {
        // Deterministic plan. Selectors/URLs are explicitly provided (no inference).
        List<Action> actions = new ArrayList<>();

        actions.add(new Action(Action.Type.NAVIGATE, null, "https://www.cse.lk/"));

        // Example: just take a screenshot after navigation.
        // Replace with your real selectors/actions for the target site.
        actions.add(new Action(Action.Type.SCREENSHOT, null, null));

        return actions;
    }
}

package ui_adapter.agent;

import ui_adapter.model.Action;
import ui_adapter.model.ActionResult;

import java.util.List;

public interface TestAgent {
    Action nextAction(ActionResult previousResult);

    boolean isTestComplete();

    void onTestEnd(List<ActionResult> results);
}

package ui_adapter.driver;

import com.microsoft.playwright.Page;

public interface BrowserDriver extends AutoCloseable {
    void start();
    Page getPage();
    void close();
    byte[] takeScreenshot();
}

package ui_adapter.driver;

import com.microsoft.playwright.Page;
import java.util.List;

public interface BrowserDriver extends AutoCloseable {
    void start();
    Page getPage();
    
    // Add capability to handle multiple pages
    List<Page> getAllPages();
    void switchToPage(int index);
    
    void close();
    byte[] takeScreenshot();
}

package ui_adapter.driver;

import com.microsoft.playwright.*;

public class PlaywrightDriver implements BrowserDriver {
    private Playwright playwright;
    private Browser browser;
    private BrowserContext context;
    private Page page;

    @Override
    public void start() {
        playwright = Playwright.create();
        browser = playwright.chromium().launch(new BrowserType.LaunchOptions().setHeadless(false));
        context = browser.newContext();
        page = context.newPage();
    }

    @Override
    public Page getPage() {
        if (page == null) {
            throw new IllegalStateException("Driver not started. Call start() first.");
        }
        return page;
    }

    @Override
    public byte[] takeScreenshot() {
        if (page == null) {
            return new byte[0];
        }
        return page.screenshot(new Page.ScreenshotOptions()
                .setFullPage(true));
    }

    @Override
    public void close() {
        if (context != null) {
            context.close();
        }
        if (browser != null) {
            browser.close();
        }
        if (playwright != null) {
            playwright.close();
        }
    }
}

package ui_adapter.driver;

import com.microsoft.playwright.*;

public class PlaywrightDriver implements BrowserDriver {
    private Playwright playwright;
    private Browser browser;
    private BrowserContext context;
    private Page page;

    @Override
    public void start() {
        playwright = Playwright.create();
        browser = playwright.chromium().launch(new BrowserType.LaunchOptions().setHeadless(false));
        context = browser.newContext();
        page = context.newPage();
    }

    @Override
    public Page getPage() {
        if (page == null) {
            throw new IllegalStateException("Driver not started. Call start() first.");
        }
        return page;
    }

    @Override
    public java.util.List<Page> getAllPages() {
        if (context == null) {
            throw new IllegalStateException("Driver not started. Call start() first.");
        }
        return context.pages();
    }

    @Override
    public void switchToPage(int index) {
        if (context == null) {
            throw new IllegalStateException("Driver not started. Call start() first.");
        }
        java.util.List<Page> pages = context.pages();
        if (index < 0 || index >= pages.size()) {
            throw new IllegalArgumentException("Invalid page index: " + index + ". Total pages: " + pages.size());
        }
        this.page = pages.get(index);
        this.page.bringToFront();
    }

    @Override
    public byte[] takeScreenshot() {
        if (page == null) {
            return new byte[0];
        }
        return page.screenshot(new Page.ScreenshotOptions()
                .setFullPage(true));
    }

    @Override
    public void close() {
        if (context != null) {
            context.close();
        }
        if (browser != null) {
            browser.close();
        }
        if (playwright != null) {
            playwright.close();
        }
    }
}

package ui_adapter.error;

public enum ErrorType {
    TIMEOUT,
    ELEMENT_NOT_FOUND,
    ASSERTION_FAILED,
    NAVIGATION_FAILED,
    UNKNOWN_ERROR
}

package ui_adapter.error;

public enum ErrorType {
    TIMEOUT,
    ELEMENT_NOT_FOUND,
    AMBIGUOUS_SELECTOR,
    ASSERTION_FAILED,
    NAVIGATION_FAILED,
    UNKNOWN_ERROR
}

package ui_adapter.executor;

import com.microsoft.playwright.Locator;
import com.microsoft.playwright.Page;
import com.microsoft.playwright.PlaywrightException;
import com.microsoft.playwright.TimeoutError;
import com.microsoft.playwright.options.WaitForSelectorState;
import ui_adapter.driver.BrowserDriver;
import ui_adapter.error.ErrorType;
import ui_adapter.model.Action;
import ui_adapter.model.ActionResult;
import ui_adapter.selector.SelectorResolver;

import java.nio.file.Paths;
import java.util.UUID;

import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;

public class ActionExecutor {
    private final BrowserDriver driver;
    private final SelectorResolver selectorResolver;

    public ActionExecutor(BrowserDriver driver, SelectorResolver selectorResolver) {
        this.driver = driver;
        this.selectorResolver = selectorResolver;
    }

    public ActionResult execute(Action action) {
        try {
            Page page = driver.getPage();
            // Selector might be null for actions like NAVIGATE (sometimes) or SCREENSHOT
            Locator locator = selectorResolver.resolve(page, action.getSelector());

            switch (action.getType()) {
                case NAVIGATE:
                    if (action.getValue() == null || action.getValue().isEmpty()) {
                        return ActionResult.fail("Navigation URL is missing", ErrorType.NAVIGATION_FAILED, null);
                    }
                    page.navigate(action.getValue());
                    return ActionResult.pass("Navigated to " + action.getValue());

                case CLICK:
                    locator.click();
                    return ActionResult.pass("Clicked element " + action.getSelector());

                case TYPE:
                    locator.fill(action.getValue());
                    return ActionResult.pass("Typed '" + action.getValue() + "' into " + action.getSelector());

                case WAIT_FOR_VISIBLE:
                    locator.waitFor(new Locator.WaitForOptions().setState(WaitForSelectorState.VISIBLE));
                    return ActionResult.pass("Element " + action.getSelector() + " is visible");

                case ASSERT_VISIBLE:
                    assertThat(locator).isVisible();
                    return ActionResult.pass("Assertion passed: Element " + action.getSelector() + " is visible");

                case ASSERT_TEXT:
                    assertThat(locator).containsText(action.getValue());
                    return ActionResult.pass("Assertion passed: Element " + action.getSelector() + " contains text '" + action.getValue() + "'");

                case SCREENSHOT:
                    String path = "screenshot-" + UUID.randomUUID() + ".png";
                    page.screenshot(new Page.ScreenshotOptions().setPath(Paths.get(path)));
                    return ActionResult.pass("Screenshot taken: " + path);

                case SCROLL:
                    // If selector is present, scroll into view of that element
                    if (action.getSelector() != null) {
                        locator.scrollIntoViewIfNeeded();
                        return ActionResult.pass("Scrolled element " + action.getSelector() + " into view");
                    }
                    // Otherwise, generic scroll down (e.g., 500px)
                    else {
                        page.evalOnSelector("body", "body => window.scrollBy(0, 500)");
                        return ActionResult.pass("Scrolled down 500px");
                    }

                case SWITCH_TAB:
                    try {
                        // The 'value' field can hold the index (0, 1, 2)
                        int index = Integer.parseInt(action.getValue());
                        driver.switchToPage(index);
                        return ActionResult.pass("Switched to tab index " + index);
                    } catch (NumberFormatException e) {
                        // Default to switching to the last opened tab (likely the popup) if no valid index is provided
                        java.util.List<Page> pages = driver.getAllPages();
                        if (pages.size() > 1) {
                            driver.switchToPage(pages.size() - 1);
                            return ActionResult.pass("Switched to latest tab (total tabs: " + pages.size() + ")");
                        } else {
                            return ActionResult.pass("Only one tab open. No switch performed.");
                        }
                    }

                default:
                     return ActionResult.fail("Unsupported action type: " + action.getType(), ErrorType.UNKNOWN_ERROR, null);
            }
        } catch (TimeoutError e) {
             return handleFailure(e, ErrorType.TIMEOUT, "Timeout executing " + action.getType());
        } catch (PlaywrightException e) {
             // Basic error mapping
             if (e.getMessage().contains("Target closed") || e.getMessage().contains("browser has been closed")) {
                 return handleFailure(e, ErrorType.UNKNOWN_ERROR, "Browser closed unexpectedly");
             }
             if (e.getMessage().contains("NS_ERROR_UNKNOWN_HOST")) {
                 return handleFailure(e, ErrorType.NAVIGATION_FAILED, "Navigation failed: Unknown Host");
             }
             if (e.getMessage().contains("navigating to")) {
                 return handleFailure(e, ErrorType.NAVIGATION_FAILED, "Navigation failed");
             }
             if (e.getMessage().contains("strict mode violation") || e.getMessage().contains("resolved to 2 elements")) {
                 return handleFailure(e, ErrorType.AMBIGUOUS_SELECTOR, "Ambiguous selector. Found multiple elements.");
             }
             if (e.getMessage().contains("Element is not attached to the DOM")) {
                 return handleFailure(e, ErrorType.ELEMENT_NOT_FOUND, "Element not found or detached");
             }
             return handleFailure(e, ErrorType.UNKNOWN_ERROR, e.getMessage());
        } catch (AssertionError e) {
             // Playwright assertions throw AssertionError on failure
             return handleFailure(new RuntimeException(e.getMessage()), ErrorType.ASSERTION_FAILED, "Assertion failed");
        } catch (Exception e) {
            return handleFailure(e, ErrorType.UNKNOWN_ERROR, "Unexpected error: " + e.getMessage());
        }
    }

    private ActionResult handleFailure(Exception e, ErrorType type, String message) {
        String screenshotPath = null;
        try {
             // Attempt screenshot on failure
             screenshotPath = "screenshots/failure-" + UUID.randomUUID() + ".png";
             if (driver != null) {
                 driver.getPage().screenshot(new Page.ScreenshotOptions().setPath(Paths.get(screenshotPath)));
             }
        } catch (Exception ignored) {
            // If screenshot fails (e.g. browser closed), we still want to return the original error
            screenshotPath = "screenshot-failed";
        }
        return ActionResult.fail(message + " | Cause: " + e.getMessage(), type, screenshotPath);
    }
}

package ui_adapter.executor;

import com.microsoft.playwright.ElementHandle;
import com.microsoft.playwright.Locator;
import com.microsoft.playwright.Page;
import com.microsoft.playwright.PlaywrightException;
import com.microsoft.playwright.TimeoutError;
import com.microsoft.playwright.options.WaitForSelectorState;
import ui_adapter.driver.BrowserDriver;
import ui_adapter.error.ErrorType;
import ui_adapter.model.Action;
import ui_adapter.model.ActionResult;
import ui_adapter.selector.SelectorResolver;

import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;

public class ActionExecutor {
    private final BrowserDriver driver;
    private final SelectorResolver selectorResolver;

    private static final int AMBIGUOUS_CANDIDATE_LIMIT = 5;

    public ActionExecutor(BrowserDriver driver, SelectorResolver selectorResolver) {
        this.driver = driver;
        this.selectorResolver = selectorResolver;
    }

    public ActionResult execute(Action action) {
        Locator locator = null;
        try {
            Page page = driver.getPage();
            // Selector might be null for actions like NAVIGATE (sometimes) or SCREENSHOT
            locator = selectorResolver.resolve(page, action.getSelector());

            switch (action.getType()) {
                case NAVIGATE:
                    if (action.getValue() == null || action.getValue().isEmpty()) {
                        return ActionResult.fail("Navigation URL is missing", ErrorType.NAVIGATION_FAILED, null);
                    }
                    page.navigate(action.getValue());
                    return ActionResult.pass("Navigated to " + action.getValue());

                case CLICK:
                    locator.click();
                    return ActionResult.pass("Clicked element " + action.getSelector());

                case TYPE:
                    locator.fill(action.getValue());
                    return ActionResult.pass("Typed '" + action.getValue() + "' into " + action.getSelector());

                case WAIT_FOR_VISIBLE:
                    locator.waitFor(new Locator.WaitForOptions().setState(WaitForSelectorState.VISIBLE));
                    return ActionResult.pass("Element " + action.getSelector() + " is visible");

                case ASSERT_VISIBLE:
                    assertThat(locator).isVisible();
                    return ActionResult.pass("Assertion passed: Element " + action.getSelector() + " is visible");

                case ASSERT_TEXT:
                    assertThat(locator).containsText(action.getValue());
                    return ActionResult.pass("Assertion passed: Element " + action.getSelector() + " contains text '" + action.getValue() + "'");

                case SCREENSHOT:
                    String path = "screenshot-" + UUID.randomUUID() + ".png";
                    page.screenshot(new Page.ScreenshotOptions().setPath(Paths.get(path)));
                    return ActionResult.pass("Screenshot taken: " + path);

                case SCROLL:
                    // If selector is present, scroll into view of that element
                    if (action.getSelector() != null) {
                        locator.scrollIntoViewIfNeeded();
                        return ActionResult.pass("Scrolled element " + action.getSelector() + " into view");
                    }
                    // Otherwise, generic scroll down (e.g., 500px)
                    else {
                        page.evalOnSelector("body", "body => window.scrollBy(0, 500)");
                        return ActionResult.pass("Scrolled down 500px");
                    }

                case SWITCH_TAB:
                    try {
                        // The 'value' field can hold the index (0, 1, 2)
                        int index = Integer.parseInt(action.getValue());
                        driver.switchToPage(index);
                        return ActionResult.pass("Switched to tab index " + index);
                    } catch (NumberFormatException e) {
                        // Default to switching to the last opened tab (likely the popup) if no valid index is provided
                        java.util.List<Page> pages = driver.getAllPages();
                        if (pages.size() > 1) {
                            driver.switchToPage(pages.size() - 1);
                            return ActionResult.pass("Switched to latest tab (total tabs: " + pages.size() + ")");
                        } else {
                            return ActionResult.pass("Only one tab open. No switch performed.");
                        }
                    }

                default:
                    return ActionResult.fail("Unsupported action type: " + action.getType(), ErrorType.UNKNOWN_ERROR, null);
            }
        } catch (TimeoutError e) {
            return handleFailure(e, ErrorType.TIMEOUT, "Timeout executing " + action.getType());
        } catch (PlaywrightException e) {
            String msg = e.getMessage() == null ? "" : e.getMessage();

            // Basic error mapping
            if (msg.contains("Target closed") || msg.contains("browser has been closed")) {
                return handleFailure(e, ErrorType.UNKNOWN_ERROR, "Browser closed unexpectedly");
            }
            if (msg.contains("NS_ERROR_UNKNOWN_HOST")) {
                return handleFailure(e, ErrorType.NAVIGATION_FAILED, "Navigation failed: Unknown Host");
            }
            if (msg.contains("navigating to")) {
                return handleFailure(e, ErrorType.NAVIGATION_FAILED, "Navigation failed");
            }

            // Strict-mode ambiguity handling: return candidates to help disambiguate.
            if (msg.contains("strict mode violation") || msg.contains("resolved to") || msg.contains("resolved to 2 elements")) {
                String details = buildAmbiguityDetails(locator);
                return handleFailure(e, ErrorType.AMBIGUOUS_SELECTOR,
                        "Ambiguous selector. Found multiple elements." + (details == null ? "" : (" " + details)));
            }

            if (msg.contains("Element is not attached to the DOM")) {
                return handleFailure(e, ErrorType.ELEMENT_NOT_FOUND, "Element not found or detached");
            }
            return handleFailure(e, ErrorType.UNKNOWN_ERROR, msg);
        } catch (AssertionError e) {
            // Playwright assertions throw AssertionError on failure
            return handleFailure(new RuntimeException(e.getMessage()), ErrorType.ASSERTION_FAILED, "Assertion failed");
        } catch (Exception e) {
            return handleFailure(e, ErrorType.UNKNOWN_ERROR, "Unexpected error: " + e.getMessage());
        }
    }

    private String buildAmbiguityDetails(Locator locator) {
        if (locator == null) {
            return null;
        }
        try {
            int count = locator.count();
            int limit = Math.min(count, AMBIGUOUS_CANDIDATE_LIMIT);
            if (count <= 1 || limit <= 0) {
                return null;
            }

            List<String> candidates = new ArrayList<>();
            for (int i = 0; i < limit; i++) {
                Locator nth = locator.nth(i);
                ElementHandle h = nth.elementHandle();
                if (h == null) {
                    continue;
                }

                // Collect a few stable hints
                String tag = safeEval(h, "e => e.tagName.toLowerCase()");
                String text = safeEval(h, "e => (e.innerText || e.textContent || '').trim()");
                if (text != null && text.length() > 120) {
                    text = text.substring(0, 120) + "...";
                }
                String aria = safeEval(h, "e => e.getAttribute('aria-label') || ''");
                String placeholder = safeEval(h, "e => e.getAttribute('placeholder') || ''");
                String testId = safeEval(h, "e => e.getAttribute('data-testid') || e.getAttribute('data-test-id') || ''");

                candidates.add(String.format("#%d tag=%s text='%s' ariaLabel='%s' placeholder='%s' testId='%s'", i,
                        emptyToDash(tag), emptyToDash(text), emptyToDash(aria), emptyToDash(placeholder), emptyToDash(testId)));
            }

            return "Candidates(" + count + "): " + String.join(" | ", candidates) +
                    ". Hint: refine using selector.meta.nearText, selector.meta.role, LABEL/PLACEHOLDER, or choose an index.";
        } catch (Exception ignored) {
            return null;
        }
    }

    private static String safeEval(ElementHandle h, String expression) {
        try {
            Object v = h.evalOnSelector(":scope", expression);
            return v == null ? "" : String.valueOf(v);
        } catch (Exception e) {
            try {
                Object v = h.evaluate(expression);
                return v == null ? "" : String.valueOf(v);
            } catch (Exception ignored) {
                return "";
            }
        }
    }

    private static String emptyToDash(String s) {
        if (s == null) {
            return "-";
        }
        String t = s.trim();
        return t.isEmpty() ? "-" : t;
    }

    private ActionResult handleFailure(Exception e, ErrorType type, String message) {
        String screenshotPath = null;
        try {
            // Attempt screenshot on failure
            screenshotPath = "screenshots/failure-" + UUID.randomUUID() + ".png";
            if (driver != null) {
                driver.getPage().screenshot(new Page.ScreenshotOptions().setPath(Paths.get(screenshotPath)));
            }
        } catch (Exception ignored) {
            // If screenshot fails (e.g. browser closed), we still want to return the original error
            screenshotPath = "screenshot-failed";
        }
        return ActionResult.fail(message + " | Cause: " + e.getMessage(), type, screenshotPath);
    }
}

package ui_adapter.model;

public class Action {
    public enum Type {
        NAVIGATE,
        CLICK,
        TYPE,
        WAIT_FOR_VISIBLE,
        ASSERT_VISIBLE,
        ASSERT_TEXT,
        SCREENSHOT,
        SCROLL
    }

    private final Type type;
    private final Selector selector;
    private final String value; // For TYPE, NAVIGATE (url), ASSERT_TEXT

    public Action(Type type, Selector selector, String value) {
        this.type = type;
        this.selector = selector;
        this.value = value;
    }

    public Type getType() {
        return type;
    }

    public Selector getSelector() {
        return selector;
    }

    public String getValue() {
        return value;
    }

    @Override
    public String toString() {
        return "Action{" +
                "type=" + type +
                ", selector=" + selector +
                ", value='" + value + '\'' +
                '}';
    }
}

